// Who-Is BACnet/IP pour UG65 / Node-RED 3.0.2.
// Points importants pour que la decouverte fonctionne:
// - le node UDP in 47808 est place avant le node UDP out dans le JSON;
// - le node UDP out utilise outport=47808 pour que les I-Am unicast reviennent sur le port ecoute;
// - on evite le global broadcast seul: on envoie un broadcast dirige du LAN + un Who-Is unicast vers le device connu.
const BACNET_PORT = 47808;
const DIRECTED_BROADCAST = "192.168.0.255"; // adapter si l'UG65 n'est pas en 192.168.0.0/24
const KNOWN_DEVICE_IP = "192.168.0.210";  // device fourni pour le test

const broadcastWhoIs = Buffer.from([
    0x81, 0x0b, 0x00, 0x0c, // BVLC: Original-Broadcast-NPDU, longueur 12
    0x01, 0x20,             // NPDU: version 1, destination presente
    0xff, 0xff, 0x00, 0xff, // DNET global broadcast, DLEN=0, Hop count=255
    0x10, 0x08              // APDU: unconfirmed request, Who-Is
]);

const unicastWhoIs = Buffer.from([
    0x81, 0x0a, 0x00, 0x08, // BVLC: Original-Unicast-NPDU, longueur 8
    0x01, 0x00,             // NPDU: version 1, pas de destination BACnet explicite
    0x10, 0x08              // APDU: unconfirmed request, Who-Is
]);

const messages = [
    { payload: broadcastWhoIs, ip: DIRECTED_BROADCAST, port: BACNET_PORT, topic: "bacnet/whois/directed-broadcast" },
    { payload: unicastWhoIs, ip: KNOWN_DEVICE_IP, port: BACNET_PORT, topic: "bacnet/whois/unicast-known-device" }
];
node.status({ fill: "blue", shape: "dot", text: `Who-Is vers ${DIRECTED_BROADCAST} + ${KNOWN_DEVICE_IP} depuis UDP/${BACNET_PORT}` });
return [messages];

// Decodeur minimal BACnet/IP pour decouverte, sans node externe.
// Sortie 1: devices I-Am, sortie 2: requetes UDP ReadProperty, sortie 3: points/objets trouves.
const BACNET_PORT = 47808;
const PROP_OBJECT_LIST = 76;
const PROP_OBJECT_NAME = 77;
const OBJECT_TYPES = {
    0: "analog-input", 1: "analog-output", 2: "analog-value",
    3: "binary-input", 4: "binary-output", 5: "binary-value",
    8: "device", 13: "multi-state-input", 14: "multi-state-output", 19: "multi-state-value"
};

function readUInt(buf, offset, len) {
    let v = 0;
    for (let i = 0; i < len; i++) v = (v << 8) | buf[offset + i];
    return v >>> 0;
}
function objectIdToBuffer(type, instance) {
    const value = ((type & 0x3ff) << 22) | (instance & 0x3fffff);
    return Buffer.from([(value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, value & 0xff]);
}
function decodeObjectId(buf, offset) {
    const value = readUInt(buf, offset, 4);
    const type = value >>> 22;
    const instance = value & 0x3fffff;
    return { type, instance, typeName: OBJECT_TYPES[type] || `object-type-${type}`, id: `${type}:${instance}` };
}
function tagInfo(buf, offset) {
    if (offset >= buf.length) return null;
    const b = buf[offset];
    let tag = b >>> 4;
    const context = !!(b & 0x08);
    let lvt = b & 0x07;
    let header = 1;
    if (tag === 0x0f) { tag = buf[offset + header]; header++; }
    let len = lvt;
    if (lvt === 5) { len = buf[offset + header]; header++; }
    return { tag, context, lvt, len, header, valueOffset: offset + header, next: offset + header + len };
}
function skipNpdu(buf) {
    if (buf.length < 6 || buf[0] !== 0x81) return -1;
    let i = 4;
    if (buf[i++] !== 0x01) return -1;
    const control = buf[i++];
    if (control & 0x20) {
        i += 2;
        const dlen = buf[i++];
        i += dlen + 1; // DADR + hop count
    }
    if (control & 0x08) {
        i += 2;
        const slen = buf[i++];
        i += slen;
    }
    if (control & 0x80) return -1;
    return i;
}
function parseIAm(buf, apduOffset) {
    if (buf[apduOffset] !== 0x10 || buf[apduOffset + 1] !== 0x00) return null;
    let i = apduOffset + 2;
    const tObj = tagInfo(buf, i);
    if (!tObj || tObj.tag !== 12 || tObj.context || tObj.len !== 4) return null;
    const deviceObject = decodeObjectId(buf, tObj.valueOffset);
    i = tObj.next;
    const tMax = tagInfo(buf, i);
    const maxApdu = tMax ? readUInt(buf, tMax.valueOffset, tMax.len) : null;
    i = tMax ? tMax.next : i;
    const tSeg = tagInfo(buf, i);
    const segmentation = tSeg ? readUInt(buf, tSeg.valueOffset, tSeg.len) : null;
    i = tSeg ? tSeg.next : i;
    const tVendor = tagInfo(buf, i);
    const vendorId = tVendor ? readUInt(buf, tVendor.valueOffset, tVendor.len) : null;
    return { deviceId: deviceObject.instance, object: deviceObject, maxApdu, segmentation, vendorId };
}
function nextInvoke() {
    const current = flow.get("bacnetInvoke") || 1;
    const next = current >= 255 ? 1 : current + 1;
    flow.set("bacnetInvoke", next);
    return current;
}
function contextUnsigned(tagNumber, value) {
    if (value <= 0xff) return Buffer.from([(tagNumber << 4) | 0x09, value]);
    if (value <= 0xffff) return Buffer.from([(tagNumber << 4) | 0x0a, (value >>> 8) & 0xff, value & 0xff]);
    return Buffer.from([(tagNumber << 4) | 0x0c, (value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, value & 0xff]);
}
function buildReadProperty(device, objectType, objectInstance, propertyId, arrayIndex, pendingType) {
    const invokeId = nextInvoke();
    const apduParts = [
        Buffer.from([0x00, 0x05, invokeId, 0x0c]), // confirmed request, max APDU, invoke, ReadProperty
        Buffer.from([0x0c]), objectIdToBuffer(objectType, objectInstance),
        contextUnsigned(1, propertyId)
    ];
    if (arrayIndex !== undefined && arrayIndex !== null) apduParts.push(contextUnsigned(2, arrayIndex));
    const npdu = Buffer.from([0x01, 0x04]); // version 1 + expecting reply
    const body = Buffer.concat([npdu, ...apduParts]);
    const bvlc = Buffer.from([0x81, 0x0a, (body.length + 4) >>> 8, (body.length + 4) & 0xff]);
    const pending = flow.get("bacnetPending") || {};
    pending[invokeId] = { type: pendingType, deviceKey: device.key, objectType, objectInstance, propertyId, arrayIndex };
    flow.set("bacnetPending", pending);
    return { payload: Buffer.concat([bvlc, body]), ip: device.ip, port: device.port || BACNET_PORT };
}
function parseComplexAck(buf, apduOffset) {
    if ((buf[apduOffset] >>> 4) !== 3) return null;
    const invokeId = buf[apduOffset + 1];
    const service = buf[apduOffset + 2];
    if (service !== 0x0c) return null;
    let i = apduOffset + 3;
    const tObj = tagInfo(buf, i);
    if (!tObj || !tObj.context || tObj.tag !== 0) return null;
    const object = decodeObjectId(buf, tObj.valueOffset);
    i = tObj.next;
    const tProp = tagInfo(buf, i);
    if (!tProp || !tProp.context || tProp.tag !== 1) return null;
    const propertyId = readUInt(buf, tProp.valueOffset, tProp.len);
    i = tProp.next;
    let arrayIndex = null;
    const maybeArray = tagInfo(buf, i);
    if (maybeArray && maybeArray.context && maybeArray.tag === 2) {
        arrayIndex = readUInt(buf, maybeArray.valueOffset, maybeArray.len);
        i = maybeArray.next;
    }
    // Dans un ReadProperty-ACK BACnet, la valeur n'est pas directement a i:
    // elle est encapsulee dans un opening tag contextuel [3] (0x3e), puis un closing tag [3] (0x3f).
    // L'ancienne version essayait donc de decoder 0x3e comme une valeur BACnet et s'arretait avant objectList[0].
    if (buf[i] !== 0x3e) return null;
    const valueOffset = i + 1;
    const valueEnd = buf.indexOf(0x3f, valueOffset);
    return { invokeId, object, propertyId, arrayIndex, valueOffset, valueEnd: valueEnd >= 0 ? valueEnd : buf.length };
}
function decodeUnsignedApplication(buf, offset) {
    const t = tagInfo(buf, offset);
    if (!t || t.context || t.tag !== 2) return null;
    return readUInt(buf, t.valueOffset, t.len);
}
function decodeObjectIdApplication(buf, offset) {
    const t = tagInfo(buf, offset);
    if (!t || t.context || t.tag !== 12 || t.len !== 4) return null;
    return decodeObjectId(buf, t.valueOffset);
}
function decodeStringApplication(buf, offset) {
    const t = tagInfo(buf, offset);
    if (!t || t.context || t.tag !== 7 || t.len < 1) return null;
    // Premier octet = encoding BACnet. 0 est courant pour ANSI/UTF-8 compatible ASCII.
    return buf.slice(t.valueOffset + 1, t.valueOffset + t.len).toString("utf8").replace(/\u0000/g, "");
}

const buf = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload || []);
const apduOffset = skipNpdu(buf);
if (apduOffset < 0 || apduOffset >= buf.length) return null;
const sourceIp = msg.ip || msg._session?.remoteAddress || "unknown";
const sourcePort = msg.port || msg._session?.remotePort || BACNET_PORT;

const iam = parseIAm(buf, apduOffset);
if (iam) {
    const key = `${sourceIp}:${iam.deviceId}`;
    const devices = flow.get("bacnetDevices") || {};
    devices[key] = { key, ip: sourceIp, port: sourcePort, lastSeen: new Date().toISOString(), ...iam, objectCount: null, points: {} };
    flow.set("bacnetDevices", devices);
    node.status({fill: "green", shape: "dot", text: `I-Am ${iam.deviceId} @ ${sourceIp}`});
    const deviceMsg = { payload: devices[key], topic: `bacnet/device/${iam.deviceId}` };
    const readCount = buildReadProperty(devices[key], 8, iam.deviceId, PROP_OBJECT_LIST, 0, "objectListCount");
    return [deviceMsg, readCount, null];
}

const ack = parseComplexAck(buf, apduOffset);
if (!ack) return null;
const pending = flow.get("bacnetPending") || {};
const req = pending[ack.invokeId];
if (!req) return null;
delete pending[ack.invokeId];
flow.set("bacnetPending", pending);
const devices = flow.get("bacnetDevices") || {};
const device = devices[req.deviceKey];
if (!device) return null;

if (req.type === "objectListCount") {
    const count = decodeUnsignedApplication(buf, ack.valueOffset);
    if (count === null) return null;
    device.objectCount = count;
    device.nextObjectIndex = 1;
    devices[req.deviceKey] = device;
    flow.set("bacnetDevices", devices);
    node.status({fill: "blue", shape: "dot", text: `${device.deviceId}: ${count} objets`});
    return [null, buildReadProperty(device, 8, device.deviceId, PROP_OBJECT_LIST, 1, "objectListItem"), null];
}
if (req.type === "objectListItem") {
    const object = decodeObjectIdApplication(buf, ack.valueOffset);
    if (!object) return null;
    device.points[object.id] = { ...object, name: null };
    device.nextObjectIndex = (req.arrayIndex || 0) + 1;
    devices[req.deviceKey] = device;
    flow.set("bacnetDevices", devices);
    const nameReq = buildReadProperty(device, object.type, object.instance, PROP_OBJECT_NAME, null, "objectName");
    return [null, nameReq, { payload: { deviceId: device.deviceId, ip: device.ip, point: device.points[object.id] }, topic: `bacnet/point/${device.deviceId}/${object.id}` }];
}
if (req.type === "objectName") {
    const name = decodeStringApplication(buf, ack.valueOffset);
    const objectId = `${req.objectType}:${req.objectInstance}`;
    if (!device.points[objectId]) device.points[objectId] = { type: req.objectType, instance: req.objectInstance, typeName: OBJECT_TYPES[req.objectType] || `object-type-${req.objectType}`, id: objectId };
    device.points[objectId].name = name;
    devices[req.deviceKey] = device;
    flow.set("bacnetDevices", devices);
    let nextReq = null;
    if (device.objectCount && device.nextObjectIndex <= device.objectCount) {
        nextReq = buildReadProperty(device, 8, device.deviceId, PROP_OBJECT_LIST, device.nextObjectIndex, "objectListItem");
    } else {
        node.status({fill: "green", shape: "ring", text: `${device.deviceId}: decouverte terminee`});
    }
    return [null, nextReq, { payload: { deviceId: device.deviceId, ip: device.ip, point: device.points[objectId], total: device.objectCount }, topic: `bacnet/point/${device.deviceId}/${objectId}` }];
}
return null;

flow.set("bacnetDevices", {});
flow.set("bacnetPending", {});
flow.set("bacnetInvoke", 1);
node.status({fill: "grey", shape: "ring", text: "memoire effacee"});
msg.payload = "Memoire de decouverte BACnet effacee";
return msg;
